export function getHPMLAProfile(acNo: number): MLAProfile | undefined {
  return HP_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getHPMLAsByParty(party: string): MLAProfile[] {
  return HP_MLA_PROFILES.filter(p => p.party === party);
}

export function getHPFemaleMLAs(): MLAProfile[] {
  return HP_MLA_PROFILES.filter(p => p.gender === 'F');
}
